const byId=new Map(recipes.map(r=>[r.id,r]));
const prefix="thunder-extract-";
const dep=r=>prefix+r.key+"@1";
const partId=(r,role)=>prefix+r.key+"-"+role.role;
const byPart=new Map();
const num=n=>Number(n).toFixed(8);
const definitions=[];
for(const r of recipes)for(const role of r.roles){
 const id=partId(r,role);byPart.set(id,{r,role});
 const weights=r.roles.map(x=>x.index===role.index?"strength":"0.").join(",");
 definitions.push({id,version:1,name:r.name+"・"+role.name,category:"雷・抽出",view:"BOTH",duration:Math.max(.05,r.duration*(role.end-role.start)),description:"完成した雷GLSLから "+role.name+" の描画寄与を分離。強度・時刻・位置・倍率・回転を編集可能。",dependencies:["fire-common@1",dep(r)],params:[
 {id:"strength",name:"放電・発光強度",type:"float",min:0,max:3,default:1,step:.05},
 {id:"phaseStart",name:"原演出の開始位置",type:"float",min:0,max:1,default:role.start,step:.005},
 {id:"phaseEnd",name:"原演出の終了位置",type:"float",min:0,max:1,default:role.end,step:.005},
 {id:"formation",name:"発動形成あり",type:"bool",default:false}
 ],body:"float h=mix(phaseStart,phaseEnd,q);return "+r.fn+"(p,t,h,t,formation?1.:0.,"+weights+");"});
}
const deps=new Map(recipes.map(r=>[dep(r),r.code]));
const hasDependency=d=>deps.has(d);
