  previous=x.role.index;seen.add(previous);
  if(p.x!==0||p.y!==0||p.endX!==0||p.endY!==0||p.arc!==0||p.scale!==1||p.rotation!==0||p.opacity!==1||p.speed!==1||p.timeMode!=="scene"||p.tintMix!==0||p.params.formation!==formation)return null;
